using YDot.Integration.Domain.Common;
using YDot.Integration.Domain.Enums;

namespace YDot.Integration.Domain.Entities;

/// <summary>
/// One WhatsApp template message to one number (table <c>int_wati_messages</c>) - including the
/// ones deliberately NOT sent, so the database records why every verified number did or did not
/// get a message.
///
/// <see cref="LocalMessageId"/> is generated by the worker and sent to WATI with the message
/// (WATI v2 accepts a client-supplied localMessageId per receiver). It is the idempotency key:
/// after a timeout the worker asks WATI about that id instead of guessing, and the delivery
/// status (sent, delivered, read) is followed by the same id.
///
/// A unique index on (wati job, phone number) means a number can never get two messages from
/// the same WATI job, however the recipients were assembled.
/// </summary>
public sealed class WatiMessage : Entity, ITenantScoped
{
    public Guid TenantId { get; set; }

    public Guid WatiJobId { get; set; }

    public WatiJob? WatiJob { get; set; }

    /// <summary>The batch the message was sent in; null while queued or when skipped.</summary>
    public Guid? WatiBatchId { get; set; }

    public WatiBatch? WatiBatch { get; set; }

    /// <summary>The integration job behind it (automatic sends).</summary>
    public Guid? IntegrationJobId { get; set; }

    /// <summary>The CheckNumber.ai task whose answer made the number eligible (null when a saved answer was reused).</summary>
    public Guid? CheckNumberTaskId { get; set; }

    /// <summary>The CheckNumber.ai task_id, denormalised for support queries.</summary>
    public string? CheckNumberProviderTaskId { get; set; }

    /// <summary>
    /// THE CHECK THIS NUMBER WAS PICKED FROM (int_integration_jobs.id): the job whose verified
    /// answer made it eligible. For a selection it is the job the person chose the number from (or
    /// the newest check that verified it); for an older automatic send it equals
    /// <see cref="IntegrationJobId"/>. Null only on messages recorded before 15 October 2026 by a
    /// manual broadcast, which did not keep it.
    /// </summary>
    public Guid? SourceJobId { get; set; }

    /// <summary>That job's number (INT-yyyyMMdd-NNNNNN), denormalised so exports need no join.</summary>
    public string? SourceJobNumber { get; set; }

    /// <summary>The name the source file gave for the number, as it was used for this message (e.g. for {{name}}).</summary>
    public string? ContactName { get; set; }

    public Guid PhoneNumberId { get; set; }

    public PhoneNumber? PhoneNumber { get; set; }

    public Guid? CampaignId { get; set; }

    /// <summary>Digits only, as WATI expects (e.g. "919500873627").</summary>
    public string WhatsAppNumber { get; set; } = string.Empty;

    /// <summary>What CheckNumber.ai said about the number when the message was planned.</summary>
    public WhatsAppStatus WhatsAppCheck { get; set; }

    public string TemplateName { get; set; } = string.Empty;

    public string BroadcastName { get; set; } = string.Empty;

    /// <summary>The customParams sent for this receiver, JSON array of {name, value}.</summary>
    public string ParametersJson { get; set; } = "[]";

    public WatiMessageStatus Status { get; set; } = WatiMessageStatus.Queued;

    /// <summary>Why the message was not sent (see <c>SkipReasons</c>).</summary>
    public string? SkipReason { get; set; }

    public WatiRequestStatus RequestStatus { get; set; } = WatiRequestStatus.NotSent;

    /// <summary>HTTP status of the batch call this message was part of.</summary>
    public int? HttpStatusCode { get; set; }

    /// <summary>The part of WATI's response about this receiver (jsonb).</summary>
    public string? WatiResponseJson { get; set; }

    public bool? IsValidWhatsAppNumber { get; set; }

    /// <summary>Client-generated id sent to WATI; unique.</summary>
    public string LocalMessageId { get; set; } = string.Empty;

    public string? WatiMessageId { get; set; }

    public string? WhatsAppMessageId { get; set; }

    public string? ConversationId { get; set; }

    /// <summary>WATI's statusString at the last check (SENT, DELIVERED, READ, FAILED ...).</summary>
    public string? DeliveryStatusRaw { get; set; }

    public string? FailedCode { get; set; }

    public string? FailedReason { get; set; }

    public string? ReplyText { get; set; }

    /// <summary>Send attempts beyond the first.</summary>
    public int RetryCount { get; set; }

    public string? ErrorMessage { get; set; }

    public DateTimeOffset QueuedAtUtc { get; set; }

    /// <summary>When the send request carrying this message started.</summary>
    public DateTimeOffset? StartedAtUtc { get; set; }

    /// <summary>When WATI accepted or refused it.</summary>
    public DateTimeOffset? CompletedAtUtc { get; set; }

    public long? DurationMs { get; set; }

    public DateTimeOffset? SentAtUtc { get; set; }

    public DateTimeOffset? DeliveredAtUtc { get; set; }

    public DateTimeOffset? ReadAtUtc { get; set; }

    public DateTimeOffset? RepliedAtUtc { get; set; }

    public DateTimeOffset? FailedAtUtc { get; set; }

    /// <summary>
    /// True when the sent/delivered/read times are the moments the worker OBSERVED the change
    /// (status polling), not timestamps reported by WATI.
    /// </summary>
    public bool StatusTimesObserved { get; set; }

    public int StatusCheckCount { get; set; }

    public DateTimeOffset? LastStatusCheckAtUtc { get; set; }

    public DateTimeOffset? NextStatusCheckAtUtc { get; set; }

    public DateTimeOffset UpdatedAtUtc { get; set; }

    public bool IsDeliveryFinal => Status is WatiMessageStatus.Read or WatiMessageStatus.Replied
        or WatiMessageStatus.Failed or WatiMessageStatus.Skipped;
}
